#include <iostream>
#include <string>
#include <vector>
struct CueList {
    std::vector<std::string> names;
};
int main() {
    CueList original{{"Check", "Begin"}};
    CueList copy = original; // Vector and string values are copied.
    copy.names.front() = "Inspect";
    std::cout << "original=" << original.names.front() << '\n';
    std::cout << "copy=" << copy.names.front() << '\n';
    original.names.clear();
    std::cout << "copy after clear=" << copy.names.front() << '\n';
}

#include <iostream>
#include <memory>
#include <string>
#include <vector>
int main() {
    auto original = std::make_shared<std::vector<std::string>>(
        std::initializer_list<std::string>{"Check", "Begin"});
    auto handle_copy = original; // Shares the same mutable list.
    handle_copy->front() = "Inspect";
    std::cout << "original after handle edit="
              << original->front() << '\n';
    auto value_copy = std::make_shared<std::vector<std::string>>(
        *original); // Copy the list itself into a new object.
    value_copy->front() = "Continue";
    std::cout << "original after value edit="
              << original->front() << '\n';
    std::cout << "new list=" << value_copy->front() << '\n';
}
